"""Compact six-to-ten-minute lessons prepared for September 1, 2026."""


def lesson(identifier, title, era, orientation, associations, route, locks, source_label, source_url):
    return {
        "id": identifier,
        "format": "compact-association-v1",
        "title": title,
        "era": era,
        "orientation": orientation,
        "associations": [{"label": label, "text": text} for label, text in associations],
        "iacRoute": route,
        "confusables": [{"term": term, "distinction": distinction} for term, distinction in locks],
        "sources": [{"label": source_label, "url": source_url}],
    }


